<div class="card"><div class="card-header"><h5 class="mb-0">Filter Jenis Tagihan</h5></div><div class="card-body"><div class="row g-2"><div class="col-md-3"><select id="periode" class="form-select"><option value="">Semua Tahun Ajaran</option><?php foreach($periode as $p): ?><option value="<?= $p['id'] ?>"><?= html_escape($p['periode']) ?></option><?php endforeach ?></select></div><div class="col-md-3"><select id="jenis" class="form-select"><option value="">Semua Jenis</option><?php foreach($jenis as $j): ?><option value="<?= $j['id'] ?>"><?= html_escape($j['nama_jenis']) ?></option><?php endforeach ?></select></div><div class="col-md-3"><select id="master" class="form-select"><option value="">Semua Batch/Periode</option></select></div><div class="col-md-2"><select id="kelas" class="form-select"><option value="">Semua Kelas</option><?php foreach($kelas as $k): ?><option value="<?= $k['id'] ?>"><?= html_escape($k['nama_kelas']) ?></option><?php endforeach ?></select></div><div class="col-md-1 d-grid"><button id="tampil" class="btn btn-primary"><i class="ti ti-search"></i></button></div></div></div></div>
<div class="row g-3 mb-3"><div class="col-md-3"><div class="card"><div class="card-body"><small>Target</small><h4 id="target">Rp0</h4></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Pembayaran</small><h4 id="bayar" class="text-success">Rp0</h4></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Sisa</small><h4 id="sisa" class="text-danger">Rp0</h4></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Realisasi</small><h4 id="realisasi">0%</h4></div></div></div></div>
<div class="card"><div class="card-header"><h5 class="mb-0">Realisasi Per Siswa</h5></div><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Siswa</th><th>Kelas</th><th>Tagihan</th><th>Wajib</th><th class="text-end">Tarif Akhir</th><th class="text-end">Dibayar</th><th class="text-end">Sisa</th><th>Status</th></tr></thead><tbody id="data"><tr><td colspan="8" class="empty-state">Pilih filter.</td></tr></tbody></table></div></div></div>
<script>$(function(){const money=n=>'Rp'+Number(n||0).toLocaleString('id-ID');function masters(){$.post('<?= base_url('tagihan_per_jenis/master') ?>',{id_periode:$('#periode').val(),id_jenis:$('#jenis').val()},r=>$('#master').html('<option value="">Semua Batch/Periode</option>'+r.map(x=>`<option value="${x.id}">${escapeHtml(x.nama_tagihan)} (${escapeHtml(x.tipe_tagihan)})</option>`).join('')),'json')}$('#periode,#jenis').change(masters);$('#tampil').click(()=>{$.post('<?= base_url('tagihan_per_jenis/result') ?>',{id_periode:$('#periode').val(),id_jenis:$('#jenis').val(),id_master:$('#master').val(),id_kelas_setting:$('#kelas').val()},r=>{$('#target').text(money(r.summary.target));$('#bayar').text(money(r.summary.bayar));$('#sisa').text(money(r.summary.sisa));$('#realisasi').text(r.summary.realisasi+'%');$('#data').html(r.rows.length?r.rows.map(x=>`<tr><td>${escapeHtml(x.nama_siswa)}<br><small>${escapeHtml(x.nis)}</small></td><td>${escapeHtml(x.nama_kelas)}</td><td>${escapeHtml(x.nama_tagihan)}<br><small>${escapeHtml((x.nama_bulan||'')+' '+x.tahun)}</small></td><td>${x.dianggap_tunggakan==='Ya'?'Ya':'Tidak'}</td><td class="text-end">${money(x.nominal_tagihan)}</td><td class="text-end">${money(x.nominal_dibayar)}</td><td class="text-end">${money(x.sisa_tagihan)}</td><td>${escapeHtml(x.status_pembayaran)}</td></tr>`).join(''):'<tr><td colspan="8" class="empty-state">Tidak ada data.</td></tr>')},'json').fail(ajaxError)})});</script>
